<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agenda · Yeral Stecti</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet"><style>body{margin:0;background:#fcfafb;color:#332d35;font:14px 'DM Sans',sans-serif}.page{max-width:1120px;margin:auto;padding:34px}.top{display:flex;justify-content:space-between;align-items:center;gap:15px}h1{font:700 30px 'Playfair Display',serif;margin:0}.back{color:#c23973;text-decoration:none;font-weight:600}.filters,.item{background:#fff;border:1px solid #f0e6ea;border-radius:14px}.filters{display:flex;gap:10px;flex-wrap:wrap;padding:15px;margin:25px 0}input,select,button{border:1px solid #e5d9de;border-radius:8px;padding:9px 10px;font:inherit;background:#fff}button{background:#dc4f87;border-color:#dc4f87;color:#fff;cursor:pointer;font-weight:600}.status{border:0;padding:5px 7px;font-size:11px}.item{display:grid;grid-template-columns:105px 1fr auto;gap:18px;align-items:center;padding:16px;margin:10px 0}.time{font-weight:700;color:#a63062}.meta{color:#817780;font-size:12px;margin-top:5px}.badge{padding:5px 8px;border-radius:99px;font-size:11px;font-weight:700}.programada{background:#fff4df;color:#a96d13}.confirmada,.realizada{background:#e4f7f0;color:#15775a}.cancelada,.no_asistio{background:#fff0f2;color:#c53d57}.en_espera,.en_atencion{background:#f1eaff;color:#6e44b7}.empty{padding:35px;text-align:center;color:#817780}.notice{padding:10px;background:#e4f7f0;color:#15775a;border-radius:9px}@media(max-width:650px){.page{padding:20px}.item{grid-template-columns:1fr}.top{align-items:flex-start}}</style></head><body><main class="page"><header class="top"><div><a class="back" href="{{ route('dashboard') }}">← Panel general</a><h1>Agenda y citas</h